<template><main class="account-page page-width"><div class="auth-card"><div class="auth-art"><div class="auth-logo">Yu'<b>Mart</b></div><h2>Good things<br>start here.</h2><p>Your little corner for everyday favourites.</p><img src="@/assets/brands/pringles_ad1.png" alt="Snack favourites"></div><form class="auth-form" @submit.prevent="submit"><span class="eyebrow">WELCOME TO YUMART</span><h1>{{ registering ? 'Create your account' : 'Welcome back' }}</h1><p>{{ registering ? 'A few details and you’re part of the family.' : 'Sign in to see your orders and saved favourites.' }}</p><label v-if="registering">Full name<input v-model="name" required placeholder="Your name"></label><label>Email address<input v-model="email" type="email" required placeholder="you@example.com"></label><label>Password<input v-model="password" type="password" minlength="6" required placeholder="At least 6 characters"></label><p v-if="error" class="error">{{ error }}</p><button class="submit">{{ registering ? 'Create account' : 'Sign in' }} <Icon icon="mdi:arrow-right"/></button><p class="switch">{{ registering ? 'Already have an account?' : 'New around here?' }} <button type="button" @click="registering=!registering;error=''">{{ registering ? 'Sign in' : 'Create an account' }}</button></p><small class="demo-note">Demo account flow: connect an authentication API before using this for real customers.</small></form></div></main></template>
<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '@/stores/auth'
const router=useRouter(), auth=useAuthStore()
const registering=ref(false),name=ref(''),email=ref(''),password=ref(''),error=ref('')
function submit(){try{registering.value?auth.signUp(name.value,email.value,password.value):auth.signIn(email.value,password.value);router.push('/orders')}catch(e){error.value=e.message}}
</script>
<style scoped>
